// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amountA, uint256 amountB, address actor) public {
        // Each deposit must be strictly above MinDeposit (1 ether) to count.
        amountA = bound(amountA, 1 ether + 1, 1e30);
        amountB = bound(amountB, 1 ether + 1, 1e30);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        vm.deal(actor, amountA + amountB);

        vm.startPrank(actor);
        c.Deposit{value: amountA}();
        c.Deposit{value: amountB}();
        vm.stopPrank();

        // Universal rule: deposits accumulate; balance is the sum of all deposits made.
        assertTrue(c.balances(actor) == amountA + amountB);
    }
}
